import path from 'node:path';
export async function assertManualListing({page,frame,check,out,ready,row,writes}){
 const search=frame.locator('#ui011-search'),operation=frame.locator('.inventory-listing-editor');
 const open=async(code,kind)=>{await search.fill(code);const item=row(code),label=kind==='publish'?'产品上架':'产品下架';check(await item.getByRole('button',{name:label+' '+code,exact:true}).isEnabled(),`${code} ${label}可人工操作`);await item.getByRole('button',{name:label+' '+code,exact:true}).click();await operation.getByRole('button',{name:'确认'+label,exact:true}).waitFor({state:'visible'});await operation.getByRole('button',{name:'确认'+label,exact:true}).isEnabled();return operation;};
 const confirm=async(label)=>{await operation.getByRole('button',{name:'确认'+label,exact:true}).click();return frame.getByRole('dialog').filter({has:page.getByRole('button',{name:'确认执行',exact:true})});};
 const finish=async()=>{await operation.getByText(/已回读并同步当前商品状态/).waitFor();check(await operation.getByRole('button',{name:'已完成',exact:true}).isDisabled(),'成功回读后不能再次提交相同状态');await operation.getByRole('button',{name:'返回商品详情',exact:true}).click();await ready();};
 await open('026','publish');let c=await confirm('产品上架');
 let release,entered,requests=0;const gate=new Promise(r=>release=r),start=new Promise(r=>entered=r);const pending=async route=>{let p;try{p=route.request().postDataJSON();}catch{}if(p?.action!=='website-action')return route.fallback();requests++;entered();await gate;return route.continue();};await page.route('**/api/**',pending);
 try{await Promise.all([c.getByRole('button',{name:'确认执行',exact:true}).click(),start]);check(await operation.getAttribute('aria-busy')==='true','人工上下架提交中有忙碌状态');check(await operation.getByRole('button',{name:'正在处理…',exact:true}).isDisabled(),'人工提交中确认按钮变样并禁用');await operation.getByRole('button',{name:'正在处理…',exact:true}).evaluate(b=>{b.click();b.click();});await page.keyboard.press('Escape');check(await operation.isVisible()&&requests===1,'提交中防重复且Esc不打断保存');release();await finish();}finally{release();await page.unroute('**/api/**',pending);}
 check((await row('026').textContent()).includes('已上架'),'来源有货下架商品人工上架后列表立即更新');check(await row('026').getByRole('button',{name:'产品上架 026',exact:true}).isDisabled()&&await row('026').getByRole('button',{name:'产品下架 026',exact:true}).isEnabled(),'有货已上架保留人工下架能力');
 await open('026','unpublish');c=await confirm('产品下架');check((await c.textContent()).includes('来源当前有货'),'人工下架有货商品明确提示来源冲突');await page.setViewportSize({width:820,height:640});await page.screenshot({path:path.join(out,'manual-unpublish-confirm-820.png')});const b=await c.getByRole('button',{name:'确认执行',exact:true}).boundingBox();check(b.y>=0&&b.y+b.height<=640,'短窗人工确认按钮可见');const before=(await writes()).length;await c.getByRole('button',{name:'取消',exact:true}).click();check((await writes()).length===before,'取消人工下架不写网站');c=await confirm('产品下架');await c.getByRole('button',{name:'确认执行',exact:true}).click();await finish();await page.setViewportSize({width:1280,height:820});
 await open('YB06','publish');c=await confirm('产品上架');check((await c.textContent()).includes('来源当前无货'),'无货人工上架有明确提醒且可确认');await c.getByRole('button',{name:'确认执行',exact:true}).click();await finish();check((await row('YB06').textContent()).includes('已上架'),'来源无货也能按人工确认上架');await open('YB06','unpublish');c=await confirm('产品下架');await c.getByRole('button',{name:'确认执行',exact:true}).click();await finish();
 await open('026','publish');c=await confirm('产品上架');let lost=0;const uncertain=async route=>{let p;try{p=route.request().postDataJSON();}catch{}if(p?.action!=='website-action')return route.fallback();lost++;await route.fetch();return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:false,error:{message:'虚构：已提交后连接中断，结果未送达页面'}})});};await page.route('**/api/**',uncertain);
 try{await c.getByRole('button',{name:'确认执行',exact:true}).click();await operation.getByText(/已提交后连接中断/).waitFor();check(await operation.getByRole('button',{name:'确认产品上架',exact:true}).isDisabled(),'提交结果不确定时禁止直接重试');check(lost===1,'结果不确定不会自动重发网站操作');await page.screenshot({path:path.join(out,'manual-listing-uncertain-1280.png')});}finally{await page.unroute('**/api/**',uncertain);}
 await operation.getByRole('button',{name:'读取这款商品最新状态',exact:true}).click();await operation.getByText('网站已上架，无需重复上架',{exact:true}).waitFor();check(await operation.getByRole('button',{name:'确认产品上架',exact:true}).isDisabled(),'读取证实已上架后不再重发上架');await operation.getByRole('button',{name:'返回商品详情',exact:true}).click();await ready();await open('026','unpublish');c=await confirm('产品下架');await c.getByRole('button',{name:'确认执行',exact:true}).click();await finish();
 await search.fill('026');await row('026').getByRole('button',{name:'查看详情',exact:true}).click();await assertDetailManualListing({page,frame,check,sequence:['publish','unpublish'],context:'已关联来源详情'});await frame.locator('#u32-back').click();await ready();
 await search.fill('VIP20');check(await row('VIP20').getByRole('button',{name:'产品上架 VIP20',exact:true}).isDisabled()&&await row('VIP20').getByRole('button',{name:'产品下架 VIP20',exact:true}).isDisabled(),'未关联网站仍禁止上下架');check((await row('VIP20').getByRole('button',{name:'产品上架 VIP20',exact:true}).getAttribute('title')).includes('关联'),'未关联按钮解释下一步');await search.fill('YB06');
}

export async function assertDetailManualListing({page,frame,check,sequence,context}){
 for(const kind of sequence){const label=kind==='publish'?'产品上架':'产品下架',opposite=kind==='publish'?'产品下架':'产品上架',tools=frame.locator('.inventory-product-tools');await tools.locator(`button[data-action-label="${label}"]:not(:disabled)`).waitFor();await tools.getByRole('button',{name:label,exact:true}).click();const box=frame.locator('.inventory-listing-editor');await box.getByRole('button',{name:'确认'+label,exact:true}).click();const c=frame.getByRole('dialog').filter({has:page.getByRole('button',{name:'确认执行',exact:true})});check((await c.textContent()).includes('网站商品 ID'),context+'确认中标注网站ID');await c.getByRole('button',{name:'确认执行',exact:true}).click();await box.getByText(/已回读并同步当前商品状态/).waitFor();await box.getByRole('button',{name:'返回商品详情',exact:true}).click();await tools.locator(`button[data-action-label="${opposite}"]:not(:disabled)`).waitFor();check(await tools.getByRole('button',{name:label,exact:true}).isDisabled(),context+label+'成功后按钮随状态更新');}
}
